begin;
select no_plan();
set local role postgres;
insert into public.organizations(id, name) values ('00000000-0000-4000-8000-000000000055', 'DEMO F9.44.5') on conflict do nothing;
insert into public.organization_members(organization_id, user_id, role) values ('00000000-0000-4000-8000-000000000055', '00000000-0000-4000-8000-000000000001', 'owner') on conflict do nothing;
grant tetopro_covering_writer to postgres;
create temp table t_d as select '[{"id":"00000000-0000-4000-8000-000000988001","name":"DEMO tégla","workType":"roof","roofType":"gable","roofMeasurementMode":"detailed","quickPlanesMatch":true,"notes":"","photoIds":[],"measurements":[{"id":"00000000-0000-4000-8000-000000988110","label":"m","value":10.5,"unit":"m","semanticType":"roof_ridge_length"},{"id":"00000000-0000-4000-8000-000000988111","label":"m","value":10.5,"unit":"m","semanticType":"roof_eave_a"},{"id":"00000000-0000-4000-8000-000000988112","label":"m","value":4.2,"unit":"m","semanticType":"roof_plane_slope_a"}]},
 {"id":"00000000-0000-4000-8000-000000988002","name":"DEMO trapéz","workType":"roof","roofType":"gable","roofMeasurementMode":"detailed","quickPlanesMatch":false,"notes":"","photoIds":[],"measurements":[{"id":"00000000-0000-4000-8000-000000988120","label":"m","value":8,"unit":"m","semanticType":"roof_ridge_length"},{"id":"00000000-0000-4000-8000-000000988121","label":"m","value":10,"unit":"m","semanticType":"roof_eave_a"},{"id":"00000000-0000-4000-8000-000000988122","label":"m","value":4,"unit":"m","semanticType":"roof_plane_slope_a"},{"id":"00000000-0000-4000-8000-000000988123","label":"m","value":9,"unit":"m","semanticType":"roof_eave_b"},{"id":"00000000-0000-4000-8000-000000988124","label":"m","value":3.5,"unit":"m","semanticType":"roof_plane_slope_b"}]},
 {"id":"00000000-0000-4000-8000-000000988003","name":"DEMO oldal","workType":"roof","roofType":"gable","roofMeasurementMode":"detailed","quickPlanesMatch":true,"notes":"","photoIds":[],"measurements":[{"id":"00000000-0000-4000-8000-000000988130","label":"m","value":8,"unit":"m","semanticType":"roof_ridge_length"},{"id":"00000000-0000-4000-8000-000000988131","label":"m","value":10,"unit":"m","semanticType":"roof_eave_a"},{"id":"00000000-0000-4000-8000-000000988132","label":"m","value":4,"unit":"m","semanticType":"roof_plane_slope_a"},{"id":"00000000-0000-4000-8000-000000988133","label":"m","value":4.1,"unit":"m","semanticType":"roof_verge_a_left"},{"id":"00000000-0000-4000-8000-000000988134","label":"m","value":4.1,"unit":"m","semanticType":"roof_verge_a_right"}]},
 {"id":"00000000-0000-4000-8000-000000988004","name":"DEMO hibás","workType":"roof","roofType":"gable","roofMeasurementMode":"detailed","quickPlanesMatch":true,"notes":"","photoIds":[],"measurements":[{"id":"00000000-0000-4000-8000-000000988140","label":"m","value":8,"unit":"m","semanticType":"roof_ridge_length"},{"id":"00000000-0000-4000-8000-000000988141","label":"m","value":10,"unit":"m","semanticType":"roof_eave_a"},{"id":"00000000-0000-4000-8000-000000988142","label":"m","value":4,"unit":"m","semanticType":"roof_plane_slope_a"},{"id":"00000000-0000-4000-8000-000000988143","label":"m","value":3.9,"unit":"m","semanticType":"roof_verge_a_left"},{"id":"00000000-0000-4000-8000-000000988144","label":"m","value":4.1,"unit":"m","semanticType":"roof_verge_a_right"}]},
 {"id":"00000000-0000-4000-8000-000000988050","name":"DEMO ereszcsatorna","workType":"gutter","elementKind":"gutter","lengthSource":{"roofSectionId":"00000000-0000-4000-8000-000000988001","role":"eave_total"},"notes":"","photoIds":[],"measurements":[{"id":"00000000-0000-4000-8000-000000988051","label":"cs","value":21,"unit":"m","semanticType":"gutter_run_length"}]}]'::jsonb as sections;
alter table t_d add column measurements jsonb;
update t_d set measurements = private.field_survey_section_measurements(sections);
grant all on t_d to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub', '00000000-0000-4000-8000-000000000001', true);
select set_config('test.survey', '00000000-0000-4000-8000-000000988000', true);
select version from public.save_field_survey_workspace(current_setting('test.survey')::uuid, '00000000-0000-4000-8000-000000000055', null, 'roof', (select measurements from t_d), 'DEMO', 0, (select sections from t_d));
select set_config('test.rev', (select id::text from public.field_survey_revisions where survey_id=current_setting('test.survey')::uuid and version=1), true);
reset role;
select ok(has_function_privilege('tetopro_covering_writer','public.save_survey_detailed_gable_geometry_source_secure(uuid,uuid,uuid,uuid,jsonb,jsonb,uuid)','EXECUTE') and not has_function_privilege('authenticated','public.save_survey_detailed_gable_geometry_source_secure(uuid,uuid,uuid,uuid,jsonb,jsonb,uuid)','EXECUTE'), 'only the restricted writer can record detailed sources');
select set_config('test.g1', (select source_id::text from public.save_survey_detailed_gable_geometry_source_secure('00000000-0000-4000-8000-000000000055', current_setting('test.survey')::uuid, current_setting('test.rev')::uuid, '00000000-0000-4000-8000-000000988001', '{"mode":"detailed","ridgeMm":10500,"eaveAMm":10500,"slopeAMm":4200,"eaveBMm":10500,"slopeBMm":4200,"planesMatch":true,"vergeAMm":[4200,4200],"vergeBMm":[4200,4200]}', '{"areas":{"combinedRoofM2":88.2},"dimensions":{"ridgeMm":10500,"eaveTotalMm":21000,"vergeTotalMm":16800}}', '00000000-0000-4000-8000-000000000001')), true);
select is((select combined_roof_m2 from public.field_survey_roof_geometry_sources where id=current_setting('test.g1')::uuid), 88.2, 'rectangular symmetric planes: 88,2 m²');
select is((select geometry_type from public.field_survey_roof_geometry_sources where id=current_setting('test.g1')::uuid), 'roof.gable.detailed', 'the source names the detailed method');
select is((select combined_roof_m2 from public.save_survey_detailed_gable_geometry_source_secure('00000000-0000-4000-8000-000000000055', current_setting('test.survey')::uuid, current_setting('test.rev')::uuid, '00000000-0000-4000-8000-000000988002', '{"mode":"detailed","ridgeMm":8000,"eaveAMm":10000,"slopeAMm":4000,"eaveBMm":9000,"slopeBMm":3500,"planesMatch":false,"vergeAMm":null,"vergeBMm":null}', '{"areas":{"combinedRoofM2":65.75},"dimensions":{"ridgeMm":8000,"eaveTotalMm":19000,"vergeTotalMm":null}}', '00000000-0000-4000-8000-000000000001')), 65.75, 'trapezoid planes: (10+8)/2*4 + (9+8)/2*3,5 = 65,75 m²');
select is((select combined_roof_m2 from public.save_survey_detailed_gable_geometry_source_secure('00000000-0000-4000-8000-000000000055', current_setting('test.survey')::uuid, current_setting('test.rev')::uuid, '00000000-0000-4000-8000-000000988003', '{"mode":"detailed","ridgeMm":8000,"eaveAMm":10000,"slopeAMm":4000,"eaveBMm":10000,"slopeBMm":4000,"planesMatch":true,"vergeAMm":[4100,4100],"vergeBMm":[4100,4100]}', '{"areas":{"combinedRoofM2":72},"dimensions":{"ridgeMm":8000,"eaveTotalMm":20000,"vergeTotalMm":16400}}', '00000000-0000-4000-8000-000000000001')), 72::numeric, 'measured sides of a trapezoid are accepted');
select is((select reused from public.save_survey_detailed_gable_geometry_source_secure('00000000-0000-4000-8000-000000000055', current_setting('test.survey')::uuid, current_setting('test.rev')::uuid, '00000000-0000-4000-8000-000000988001', '{"mode":"detailed","ridgeMm":10500,"eaveAMm":10500,"slopeAMm":4200,"eaveBMm":10500,"slopeBMm":4200,"planesMatch":true,"vergeAMm":[4200,4200],"vergeBMm":[4200,4200]}', '{"areas":{"combinedRoofM2":88.2},"dimensions":{"ridgeMm":10500,"eaveTotalMm":21000,"vergeTotalMm":16800}}', '00000000-0000-4000-8000-000000000001')), true, 'a repeated write is idempotent');
select throws_ok($$ select * from public.save_survey_detailed_gable_geometry_source_secure('00000000-0000-4000-8000-000000000055', current_setting('test.survey')::uuid, current_setting('test.rev')::uuid, '00000000-0000-4000-8000-000000988001', '{"mode":"detailed","ridgeMm":10500,"eaveAMm":10500,"slopeAMm":4200,"eaveBMm":10500,"slopeBMm":4200,"planesMatch":true,"vergeAMm":[4200,4200],"vergeBMm":[4200,4200]}', '{"areas":{"combinedRoofM2":90},"dimensions":{"ridgeMm":10500,"eaveTotalMm":21000,"vergeTotalMm":16800}}', '00000000-0000-4000-8000-000000000001') $$, '22023', null, 'a wrong caller-supplied area is rejected');
select throws_ok($$ select * from public.save_survey_detailed_gable_geometry_source_secure('00000000-0000-4000-8000-000000000055', current_setting('test.survey')::uuid, current_setting('test.rev')::uuid, '00000000-0000-4000-8000-000000988002', '{"mode":"detailed","ridgeMm":8000,"eaveAMm":10000,"slopeAMm":4000,"eaveBMm":9000,"slopeBMm":3500,"planesMatch":false,"vergeAMm":null,"vergeBMm":null}', '{"areas":{"combinedRoofM2":65.75},"dimensions":{"ridgeMm":8000,"eaveTotalMm":19000,"vergeTotalMm":99}}', '00000000-0000-4000-8000-000000000001') $$, '22023', null, 'an invented verge total is rejected');
select throws_ok($$ select * from public.save_survey_detailed_gable_geometry_source_secure('00000000-0000-4000-8000-000000000055', current_setting('test.survey')::uuid, current_setting('test.rev')::uuid, '00000000-0000-4000-8000-000000988004', '{"mode":"detailed","ridgeMm":8000,"eaveAMm":10000,"slopeAMm":4000,"eaveBMm":10000,"slopeBMm":4000,"planesMatch":true,"vergeAMm":[4100,4100],"vergeBMm":[4100,4100]}', '{"areas":{"combinedRoofM2":72},"dimensions":{"ridgeMm":8000,"eaveTotalMm":20000,"vergeTotalMm":16400}}', '00000000-0000-4000-8000-000000000001') $$, '22023', null, 'impossible side lengths never become a verified source');
select throws_ok($$ select * from public.save_survey_detailed_gable_geometry_source_secure('00000000-0000-4000-8000-000000000055', current_setting('test.survey')::uuid, current_setting('test.rev')::uuid, '00000000-0000-4000-8000-000000988001', '{"mode":"detailed","ridgeMm":10500,"eaveAMm":10400,"slopeAMm":4200,"eaveBMm":10500,"slopeBMm":4200,"planesMatch":true,"vergeAMm":[4200,4200],"vergeBMm":[4200,4200]}', '{"areas":{"combinedRoofM2":88.2},"dimensions":{"ridgeMm":10500,"eaveTotalMm":21000,"vergeTotalMm":16800}}', '00000000-0000-4000-8000-000000000001') $$, '22023', null, 'an input that differs from the revision is rejected');
select is(private.survey_detailed_gable_input((select sections from public.field_survey_revisions where survey_id=current_setting('test.survey')::uuid and version=1), '00000000-0000-4000-8000-000000988004'::uuid), null, 'a contradictory section yields no input');
set local role authenticated;
select set_config('request.jwt.claim.sub', '00000000-0000-4000-8000-000000000001', true);
create temp table t_i as select jsonb_build_array(jsonb_build_object('id','00000000-0000-4000-8000-000000988101','kind','manual','description','e1','materialCategory','gutter','categoryId',null,'quantity','21','unit','linear_meter','variantId',null,'priceId',null,'manualPriceAmount','','manualPriceKind',null,'sourceRef',jsonb_build_object('type','measurement','sectionId','00000000-0000-4000-8000-000000988050','measurementId','00000000-0000-4000-8000-000000988051'))) as items;
grant all on t_i to authenticated;
select set_config('test.list', (select list_id::text from public.save_workflow_material_list_from_survey_revision('00000000-0000-4000-8000-000000000055', current_setting('test.survey')::uuid, current_setting('test.rev')::uuid, false, 'DEMO eredet', (select items from t_i), '00000000-0000-4000-8000-000000988201')), true);
reset role;
select is((select source_items_snapshot #>> '{0,quantityKind}' from public.material_preparation_survey_sources where survey_revision_id=current_setting('test.rev')::uuid), 'calculated', 'an eave taken from a detailed roof is calculated while it matches the verified source');
select is((select (source_items_snapshot #>> '{0,origin,calculatedValueMm}')::numeric from public.material_preparation_survey_sources where survey_revision_id=current_setting('test.rev')::uuid), 21000::numeric, 'the verified eave total is recorded in the origin');
select * from finish();
rollback;
